"""Sharing images (og:image) for the anonymous pages: generated by default, replaceable in /admin/web (app/og.py)."""

import re

from app import main
from tests.helpers import full_user, otp_login

PNG = b"\x89PNG\r\n\x1a\n" + b"\0" * 32


def og_image(html: str) -> str:
    return re.search(r'<meta property="og:image" content="([^"]+)"', html).group(1)


async def admin_client(make_client):
    admin = make_client()
    await full_user(admin, "11111111")
    return admin


async def test_generated_images_are_served_and_linked(client):
    r = await client.get("/api/public/og/login")
    assert r.status_code == 200 and r.headers["content-type"] == "image/png" and r.content.startswith(b"\x89PNG")
    assert (await client.get("/api/public/og/nope")).status_code == 404
    assert (await client.get("/api/public/og/page-1")).status_code == 404

    html = (await client.get("/w/")).text
    assert "/api/public/og/w?v=" in og_image(html)
    assert '<meta name="twitter:card" content="summary_large_image">' in html
    assert '<meta property="og:site_name" content="Tørgær">' in html


async def test_admin_replaces_and_resets_a_surface(make_client, owner_conn):
    admin = await admin_client(make_client)
    user = make_client()
    await otp_login(user, "22222222")
    assert (await user.post("/api/admin/web/og/login", files={"file": ("og.png", PNG, "image/png")})).status_code == 403

    r = await admin.post("/api/admin/web/og/login", files={"file": ("og.txt", b"not an image", "image/png")})
    assert r.status_code == 400
    r = await admin.post("/api/admin/web/og/login", files={"file": ("og.png", PNG, "text/plain")})
    assert r.status_code == 200
    assert (await admin.get("/api/public/og/login")).content == PNG
    surfaces = {s["name"]: s for s in (await admin.get("/api/admin/web/og")).json()["surfaces"]}
    assert surfaces["login"]["custom"] and not surfaces["w"]["custom"]
    audit = owner_conn.execute("select after from audit_log where row_id = 'og_images.login'").fetchone()
    assert audit[0]["og_image"].startswith("settings/og/")

    # An uploaded default is used by every surface without its own upload.
    await admin.post("/api/admin/web/og/default", files={"file": ("d.png", PNG + b"d", "image/png")})
    assert (await admin.get("/api/public/og/privatliv")).content == PNG + b"d"
    assert (await admin.get("/api/public/og/login")).content == PNG

    assert (await admin.delete("/api/admin/web/og/login")).status_code == 200
    assert (await admin.get("/api/public/og/login")).content == PNG + b"d"
    await admin.delete("/api/admin/web/og/default")
    assert (await admin.get("/api/public/og/login")).content.startswith(b"\x89PNG\r\n")
    assert owner_conn.execute("select count(*) from files where storage_key like 'settings/og/%'").fetchone()[0] == 0


async def test_a_page_gets_its_own_image(make_client):
    admin = await admin_client(make_client)
    r = await admin.post("/api/admin/web", json={"slug": "og-priser", "lang": "da", "title": "Priser",
                                                 "description": "Hvad det koster", "published": True})
    assert r.status_code == 200, r.text
    page = r.json()
    assert "/api/public/og/default?v=" in og_image((await admin.get("/w/og-priser")).text)

    assert (await admin.post(f"/api/admin/web/{page['id']}/og", files={"file": ("p.png", PNG, "image/png")})).status_code == 200
    html = (await admin.get("/w/og-priser")).text
    assert f"/api/public/og/page-{page['id']}?v=" in og_image(html)
    assert '<meta property="og:description" content="Hvad det koster">' in html
    assert (await admin.get(f"/api/public/og/page-{page['id']}")).content == PNG

    assert (await admin.delete(f"/api/admin/web/{page['id']}/og")).status_code == 200
    assert "/api/public/og/default?v=" in og_image((await admin.get("/w/og-priser")).text)


async def test_app_html_gets_title_and_tags(tmp_path):
    index = tmp_path / "index.html"
    index.write_text("<html><head><title>X</title></head><body></body></html>", encoding="utf-8")
    html = await main.app_html(str(index), "/login")
    assert "<title>Log ind · Tørgær</title>" in html
    assert "/api/public/og/login?v=" in og_image(html)
    html = await main.app_html(str(index), "/privatliv")
    assert "/api/public/og/privatliv?v=" in og_image(html)
    html = await main.app_html(str(index), "/klip")
    assert "/api/public/og/default?v=" in og_image(html) and "<title>Klip · Tørgær</title>" in html
